import {html as h} from './workshop-model.js';
import {STEP_SECONDS,canWalkRecipe,tutorialIndex,recipeWalkthrough,stepAt,tutorialCoverage} from './tutorial-engine.js';
const chunks=new Map();
function getChunk(path){if(!chunks.has(path))chunks.set(path,fetch(path).then(r=>{if(!r.ok)throw Error('Modelo no disponible');return r.json();}).catch(e=>{chunks.delete(path);throw e;}));return chunks.get(path);}
export function createTutorialPlayer(c){
 const tutorials=c.data.tutorials||[],index=tutorialIndex(tutorials),modelIndex=c.data.tutorialModels?.items||{},coverage=tutorialCoverage(c.recipes,tutorials);
 let mode='',recipeId='',useId='',active=null,selected='',disposeCurrent=()=>{},filter='all';
 const resolve=i=>c.engine.resolve(i,c.state().selections);
 const chip=(item,extra='')=>{const i=typeof item==='string'?{id:item}:item;return `<button class="tut-token ${extra}" data-ws-item="${h(i.id)}" title="${h(c.name(i.id))}">${c.icon(i.id)}<span>${i.count?`<b>${i.count}${i.kind==='fluid'?' mB':'×'}</b> `:''}${h(c.name(i.id))}</span>${i.tag?'<small>alternativa</small>':''}</button>`;};
 function matches(id){return filter==='all'||filter==='use'&&index.has(id)||filter==='recipe'&&c.engine.candidates(id).some(canWalkRecipe)||filter==='model'&&Boolean(modelIndex[id]);}
 function filterView(){return `<div class="tut-filters" aria-label="Tipo de tutorial">${[['all','Todo'],['use','Con tutorial de uso'],['recipe','Fabricación animada'],['model','Modelo 3D']].map(([id,label])=>`<button data-tut-filter="${id}" class="${filter===id?'active':''}" aria-pressed="${filter===id}">${label}</button>`).join('')}</div>`;}
 function badge(id){return index.has(id)?'<span class="ws-tutorial-dot use" title="Tutorial de uso">●</span>':c.engine.candidates(id).some(canWalkRecipe)?'<span class="ws-tutorial-dot" title="Fabricación animada">▷</span>':'';}
 function render(id){
  if(selected!==id){mode='';recipeId='';useId='';selected=id;}
  const useOptions=tutorials.filter(t=>t.itemIds.includes(id)),use=useOptions.find(t=>t.id===useId)||useOptions[0],candidates=c.engine.candidates(id).filter(canWalkRecipe),r=candidates.find(r=>r.id===recipeId)||candidates[0];
  const type=mode==='recipe'&&r?'recipe':mode==='use'&&use?'use':use?'use':'recipe';
  active=type==='use'?use:r?recipeWalkthrough(r,{resolve,name:c.name,process:c.process}):null;
  if(!active)return '';
  const t=active,isRecipe=type==='recipe',done=c.state().tasks['tutorial:'+t.id]===true;
  return `<section class="tut-panel blueprint-sheet" data-tut-player data-tut-id="${h(t.id)}"><div class="tut-topline"><div class="tut-modes">${use?`<button data-tut-mode="use" class="${!isRecipe?'active':''}">▷ Cómo se usa</button>`:''}${r?`<button data-tut-mode="recipe" class="${isRecipe?'active':''}">▦ Cómo se fabrica</button>`:''}</div><label class="tut-done"><input type="checkbox" data-tut-done="${h(t.id)}" ${done?'checked':''}> Aprendido</label></div>${!isRecipe&&useOptions.length>1?`<label class="tut-recipe-select">Tutorial<select data-tut-lesson aria-label="Tutorial de uso">${useOptions.map(x=>`<option value="${h(x.id)}" ${x.id===use.id?'selected':''}>${h(x.title)}</option>`).join('')}</select></label>`:''}${isRecipe&&candidates.length>1?`<label class="tut-recipe-select">Método<select data-tut-recipe aria-label="Método de fabricación">${candidates.map((x,i)=>`<option value="${h(x.id)}" ${x.id===r.id?'selected':''}>${i+1}. ${h(c.process(x.type))} · ${h(x.id.split(':').slice(1).join(':'))}</option>`).join('')}</select></label>`:''}<div class="tut-stage ${isRecipe?'is-recipe':''}" data-tut-stage tabindex="0" aria-label="Tutorial interactivo. Espacio reproduce; flechas cambian de paso."><div class="tut-stage-heading"><span>${isRecipe?'FABRICACIÓN PASO A PASO':'TUTORIAL DE USO'}</span><h3>${h(t.title)}</h3></div><div class="tut-scene" data-tut-model><div class="tut-icon-scene">${c.icon(id)}</div></div>${isRecipe?recipeDiagram(t):''}<div class="tut-floating-note"><b data-tut-counter>01 / ${t.steps.length}</b><strong data-tut-title>${h(t.steps[0].title)}</strong><p data-tut-text>${h(t.steps[0].text)}</p></div><div class="tut-stage-label">${c.icon(id)}<span>${h(c.name(id))}</span></div><span class="tut-visual-kind" data-tut-kind>${modelIndex[id]?'Modelo 3D':'Icono del objeto'}</span></div><div class="tut-step-items" data-tut-items>${(t.steps[0].items||[]).map(x=>chip(x)).join('')}</div><div class="tut-controls"><button data-tut-action="restart" title="Reiniciar tutorial" aria-label="Reiniciar tutorial">↺</button><button data-tut-action="prev" aria-label="Paso anterior">‹</button><button data-tut-action="play" aria-label="Reproducir tutorial" aria-pressed="false">▶</button><button data-tut-action="next" aria-label="Paso siguiente">›</button><input data-tut-time type="range" min="0" max="${t.steps.length*STEP_SECONDS}" step=".05" value="0" aria-label="Progreso del tutorial"><select data-tut-speed aria-label="Velocidad del tutorial"><option value=".5">0.5×</option><option value="1" selected>1×</option><option value="1.5">1.5×</option><option value="2">2×</option></select></div><div class="tut-bottom"><span>Arrastra para girar · rueda para acercar</span><div><button data-tut-action="rotate" aria-label="Girar objeto">↻ Girar</button><button data-tut-action="zoom-out" aria-label="Alejar objeto">−</button><button data-tut-action="zoom-in" aria-label="Acercar objeto">+</button></div></div><div class="tut-chapters">${t.steps.map((s,i)=>`<button data-tut-step="${i}" class="${i===0?'active':''}" aria-current="${i===0?'step':'false'}"><b>${String(i+1).padStart(2,'0')}</b><span>${h(s.title)}</span></button>`).join('')}</div><details class="tut-sources"><summary>Fuentes y versión</summary><p>${isRecipe?'Receta del catálogo fijado a ATM10 8.1. Los materiales alternativos y condiciones se conservan en los detalles.':'Escena explicativa con modelos o iconos originales. Movimiento ilustrativo; no ejecuta el Ponder de Minecraft.'}</p>${(t.sources||[]).map(s=>`<a href="${h(s.url)}" target="_blank" rel="noopener noreferrer">${h(s.label)} ↗</a>`).join('')}${isRecipe?`<button class="btn" data-recipe="${h(r.id)}">Ver receta completa y condiciones</button>`:''}<p>Vista de estados representativos; puede omitir colores de bioma, fluidos y partes generadas por el juego. <a href="data/model-attributions.json" target="_blank" rel="noopener noreferrer">Créditos de modelos y texturas ↗</a></p><small data-tut-model-source></small></details></section>`;
 }
 function recipeDiagram(t){return `<div class="tut-recipe-diagram"><span>${h(c.process(t.recipe.type))}</span>${t.slots?`<div class="tut-craft-grid" style="--cols:${t.slots.cols}">${t.slots.slots.map((i,n)=>`<div class="tut-craft-cell" data-tut-cell="${n}">${i?`<button data-ws-item="${h(i.id)}" title="${h(c.name(i.id))}">${c.icon(i.id)}</button>`:''}</div>`).join('')}</div>`:`<div class="tut-process-icons">${t.inputs.slice(0,6).map(i=>`<div>${c.icon(i.id)}<b>${i.count}${i.kind==='fluid'?' mB':'×'}</b></div>`).join('')}${t.inputs.length>6?`<small>+${t.inputs.length-6}</small>`:''}</div>`}<div class="tut-flow-arrow">↓</div><div class="tut-output" data-tut-output>${c.icon(t.recipe.output.id)}<b>${t.recipe.output.count}×</b>${t.recipe.output.chance<1?`<small>${Math.round(t.recipe.output.chance*100)}%</small>`:''}</div></div>`;}
 function library(query='',mod='all'){
  const norm=s=>s.toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g,'');
  const shown=tutorials.filter(t=>(mod==='all'||t.itemIds.some(id=>id.startsWith(mod+':')))&&norm(t.title+' '+t.itemIds.map(c.name).join(' ')+' '+t.itemIds.join(' ')).includes(norm(query)));
  return `<div class="tut-library-intro"><span><b>${coverage.usageTutorials}</b> tutoriales de uso</span><span><b>${coverage.recipeItems.toLocaleString('es-MX')}</b> objetos con fabricación animada</span><button class="btn" data-tut-open-atlas>Explorar todos los objetos →</button></div><div class="tut-library">${shown.map(t=>`<button class="paper-panel" data-tut-library="${h(t.id)}"><div>${t.itemIds.slice(0,3).map(c.icon).join('')}</div><small>${h(t.itemIds[0].split(':')[0])} · ${t.steps.length} pasos</small><h3>${h(t.title)}</h3><span>${c.state().tasks['tutorial:'+t.id]?'✓ Aprendido':'▷ Abrir tutorial'}</span></button>`).join('')}</div>`;
 }
 function bind(root){
  const click=e=>{const el=e.target.closest('button');if(!el)return;const d=el.dataset;if(d.tutLibrary){const t=tutorials.find(t=>t.id===d.tutLibrary);selected=t.itemIds[0];useId=t.id;mode='use';c.navigate('item/'+encodeURIComponent(selected));}else if(d.tutFilter){filter=d.tutFilter;c.render();}else if(d.tutMode){mode=d.tutMode;c.render();}else if(d.tutOpenAtlas!==undefined){filter='use';c.navigate('recipes');}};
  root.addEventListener('click',click);
  const player=root.querySelector('[data-tut-player]');
  let dead=false,viewer=null,frame,last=performance.now(),time=0,speed=1,playing=false,lastStep=-1,visible=true;
  const obs=player?new IntersectionObserver(es=>{visible=es[0]?.isIntersecting??true;}):null;if(player)obs.observe(player);
  const t=active,total=(t?.steps.length||1)*STEP_SECONDS;
  const paint=()=>{
   if(!player||!t)return;const index=stepAt(time,t.steps.length),step=t.steps[index];
   const slider=player.querySelector('[data-tut-time]');if(document.activeElement!==slider)slider.value=time;
   player.style.setProperty('--tut-progress',`${time/total*100}%`);player.dataset.phase=step.phase||'use';
   viewer?.seek(time);
   if(index!==lastStep){lastStep=index;player.querySelector('[data-tut-counter]').textContent=`${String(index+1).padStart(2,'0')} / ${t.steps.length}`;player.querySelector('[data-tut-title]').textContent=step.title;player.querySelector('[data-tut-text]').textContent=step.text;player.querySelector('[data-tut-items]').innerHTML=(step.items||[]).map(x=>chip(x)).join('');player.querySelectorAll('[data-tut-step]').forEach((b,i)=>{b.classList.toggle('active',i===index);b.setAttribute('aria-current',i===index?'step':'false');});viewer?.setTutorialStep?.(step,index);}
   const cells=[...player.querySelectorAll('[data-tut-cell]')].filter(x=>x.querySelector('img'));cells.forEach((cell,i)=>cell.classList.toggle('lit',step.phase!=='ingredients'||(time%STEP_SECONDS)/STEP_SECONDS>i/Math.max(1,cells.length)));
  };
  const setPlaying=v=>{playing=v;player?.classList.toggle('playing',v);const btn=player?.querySelector('[data-tut-action="play"]');if(btn){btn.textContent=v?'Ⅱ':'▶';btn.setAttribute('aria-label',v?'Pausar tutorial':'Reproducir tutorial');btn.setAttribute('aria-pressed',String(v));}};
  const seek=v=>{time=Math.max(0,Math.min(total,v));paint();};
  const stepTo=i=>seek(Math.max(0,Math.min(t.steps.length-1,i))*STEP_SECONDS);
  const onClick=e=>{const b=e.target.closest('button');if(!b)return;const d=b.dataset;if(d.tutStep!==undefined)stepTo(Number(d.tutStep));if(d.tutAction==='play'){if(time>=total)seek(0);setPlaying(!playing);}if(d.tutAction==='restart'){seek(0);setPlaying(true);}if(d.tutAction==='prev')stepTo(lastStep-1);if(d.tutAction==='next')stepTo(lastStep+1);if(d.tutAction==='rotate')viewer?.rotate(Math.PI/4);if(d.tutAction==='zoom-in')viewer?.zoom(1.2);if(d.tutAction==='zoom-out')viewer?.zoom(1/1.2);};
  const change=e=>{const d=e.target.dataset;if(d.tutSpeed!==undefined)speed=Number(e.target.value);if(d.tutDone){c.state().tasks['tutorial:'+d.tutDone]=e.target.checked;c.save();}if(d.tutLesson!==undefined){useId=e.target.value;mode='use';c.render();}if(d.tutRecipe!==undefined){recipeId=e.target.value;mode='recipe';c.render();}};
  const input=e=>{if(e.target.dataset.tutTime!==undefined)seek(Number(e.target.value));};
  const key=e=>{if(e.target!==player.querySelector('[data-tut-stage]'))return;if([' ','ArrowLeft','ArrowRight'].includes(e.key)){e.preventDefault();if(e.key===' '){if(time>=total)seek(0);setPlaying(!playing);}else stepTo(lastStep+(e.key==='ArrowLeft'?-1:1));}};
  if(player){player.addEventListener('click',onClick);player.addEventListener('change',change);player.addEventListener('input',input);player.addEventListener('keydown',key);paint();
   const tick=now=>{if(dead)return;const dt=Math.min((now-last)/1000,.1);last=now;if(playing&&visible&&!document.hidden){time=Math.min(total,time+dt*speed);paint();if(time>=total)setPlaying(false);}frame=requestAnimationFrame(tick);};frame=requestAnimationFrame(tick);
   const host=player.querySelector('[data-tut-model]'),id=selected;
   // Items without a cuboid model use their actual inventory icon on the same stage.
   let blocks=(t.sceneBlocks?.length?t.sceneBlocks:[{id,x:0,y:0,z:0}]).map(b=>({...b}));
   const paths=[...new Set(blocks.map(b=>modelIndex[b.id]).filter(Boolean))];
   Promise.all([import('./model-viewer.js'),...paths.map(getChunk)]).then(([module,...data])=>{if(dead||!host.isConnected)return;const merged={models:Object.assign({},...data.map(d=>d.models)),textures:Object.assign({},...data.map(d=>d.textures))};if(blocks.length===1&&!merged.models[blocks[0].id]?.available&&!c.icons[blocks[0].id]){player.querySelector('[data-tut-kind]').textContent='Sin modelo 3D';return;}const scene={id:'tutorial:'+t.id,blocks,steps:t.steps};viewer=module.mountModelViewer(host,scene,merged,{icons:c.icons,iconFallback:true,tutorial:true});paint();viewer.setTutorialStep?.(t.steps[lastStep],lastStep);const original=blocks.filter(b=>merged.models[b.id]?.available).length;player.querySelector('[data-tut-kind]').textContent=original?`Modelos originales · ${original} ${original===1?'bloque':'bloques'}`:'Iconos originales';player.querySelector('[data-tut-model-source]').textContent=[...new Set(blocks.flatMap(b=>merged.models[b.id]?.sourceJars||[]))].join(' · ');}).catch(()=>{if(!dead)player.querySelector('[data-tut-kind]').textContent='Vista con icono';});
  }
  disposeCurrent=()=>{dead=true;cancelAnimationFrame(frame);obs?.disconnect();viewer?.dispose();root.removeEventListener('click',click);if(player){player.removeEventListener('click',onClick);player.removeEventListener('change',change);player.removeEventListener('input',input);player.removeEventListener('keydown',key);}};
 }
 return {render,bind,dispose(){disposeCurrent();disposeCurrent=()=>{};},matches,filterView,badge,library,index,coverage,extraIds:()=>[...index.keys()]};
}
